/**
 * Shop Branding and Print Utilities
 * Contains embedded logo data URI for 100% reliable printing without broken external image links.
 * All English words enforced in CAPS LOCK.
 */

export const SHOP_LOGO_DATA_URL = 'data:image/jpeg;base64,';

/**
 * Ensures any string containing English letters is converted to uppercase (CAPS LOCK)
 */
export function toCaps(text: string | null | undefined): string {
  if (!text) return '';
  return text.toUpperCase();
}

/**
 * Standard uppercase units for fruit wholesale billing
 */
export function getUnitInCaps(unit: string): string {
  switch (unit) {
    case 'क्यारेट':
      return 'CARAT';
    case 'कार्टुन':
      return 'BOX';
    case 'गोटा':
      return 'PIECE / NO.';
    case 'बोरा':
      return 'BAG';
    case 'पेटी':
      return 'PETI';
    case 'केजी':
      return 'KG';
    case 'दर्जन':
      return 'DOZEN';
    case 'घार':
      return 'GHAR';
    default:
      return unit ? toCaps(unit) : 'UNIT';
  }
}
